import{_ as t,H as a,f as E,i as s}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"第2季回归 | 这一次，我们一起拿下设计模式！","description":"","frontmatter":{},"headers":[],"relativePath":"数据结构与算法之美/第2季回归-这一次，我们一起拿下设计模式！.md","filePath":"数据结构与算法之美/第2季回归-这一次，我们一起拿下设计模式！.md","lastUpdated":1779820813000}'),i={name:"数据结构与算法之美/第2季回归-这一次，我们一起拿下设计模式！.md"};function n(r,e,p,_,o,m){return a(),E("div",null,[...e[0]||(e[0]=[s('<h1 id="第2季回归-这一次-我们一起拿下设计模式" tabindex="-1">第2季回归 | 这一次，我们一起拿下设计模式！ <a class="header-anchor" href="#第2季回归-这一次-我们一起拿下设计模式" aria-label="Permalink to &quot;第2季回归 | 这一次，我们一起拿下设计模式！&quot;">​</a></h1><p>你好，我是王争。“数据结构与算法之美”在今年2月底全部更新完毕。时隔8个月，我又为你带来了一个新的专栏“设计模式之美”。如果说“数据结构与算法之美”是教你如何写出高效的代码，那“设计模式之美”就是教你如何写出高质量的代码。</p><p>在设计“设计模式之美”专栏的时候，我仍然延续“数据结构与算法之美”的讲述方式。在专栏的整体设计上，我希望尽量还原一对一、手把手code review的场景，通过100篇正文和10篇不定期加餐，200多个真实的项目实战代码案例剖析，100多个有深度的课堂讨论、头脑风暴，来为你交付这个“设计模式之美”专栏。</p><p>我希望通过这个专栏，一次性把跟编写高质量代码相关的所有知识，都系统、全面地讲清楚，一次性给你讲透彻。让你看完这个专栏，就能搞清楚所有跟写高质量代码相关的知识点。</p><p>专栏共100期正文和10期不定期加餐，分为5个模块。下面是专栏的目录：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/161115/0731fd3ef440090a9b956fa69dda7920.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/161115/0731fd3ef440090a9b956fa69dda7920.jpg" alt=""></a></p><p>为了感谢老同学，我为你准备了一个专属福利：</p><p>11月4日，专栏上新时，我会送你一张30元专属优惠券，可与限时优惠同享，有效期48小时，建议尽早使用。点击下方图片，立即免费试读新专栏。</p><p>一段新的征程，期待与你一起见证成长！</p><p><a href="https://time.geekbang.org/column/intro/250?utm_term=zeusDAAF2&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=250-presell&amp;utm_content=suanfazhuanlan1104" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/161115/5f66fbdad7931304442e6815dc4b9c85.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/161115/5f66fbdad7931304442e6815dc4b9c85.jpg" alt=""></a></a></p>',10)])])}const l=t(i,[["render",n]]);export{B as __pageData,l as default};
